def open_fds():
    me = os.getpid()
    return {fd for fd in os.listdir(f"/proc/{me}/fd")}

before = open_fds()
prog = os.path.basename(sys.argv[0]).replace("-", "_").replace(".", "_")
os.environ[f"_{prog.upper()}_COMPLETE"] = "bash_complete"
os.environ["COMP_WORDS"] = f"cli sub --data {path} "
