import gc, os, sys, tempfile, warnings
sys.path.insert(0, "/scratch/manas_ase/tmp/parbench-host-74_ep9i5/repo/src")
from click import File, command, group, option

with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as f:
    f.write("{}")
    path = f.name

def run_case(name, cli, comp_words, cword):
    prog = os.path.basename(sys.argv[0]).replace("-", "_").replace(".", "_")
    os.environ[f"_{prog.upper()}_COMPLETE"] = "bash_complete"
    os.environ["COMP_WORDS"] = comp_words
    os.environ["COMP_CWORD"] = str(cword)
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        try:
            cli.main(args=[], standalone_mode=True)
        except SystemExit:
            pass
        gc.collect()
    leaks = [w for w in caught if issubclass(w.category, ResourceWarning)]
    status = "LEAK" if leaks else "OK"
    print(f"{status}: {name}")
    for w in leaks:
        print("   ", w.message)

# Case 1: 3-level group, file opt at each level
@group()
@option("--config", type=File("r"))
def top(config): pass

@top.group()
@option("--mid", type=File("r"))
def mid(mid): pass

@mid.command()
@option("--leaf", type=File("r"))
def leaf(leaf): pass

run_case("3-level", top, f"top mid leaf --leaf {path}   ", 5)
run_case("3-level mid file", top, f"top --config {path} mid leaf   ", 5)
run_case("3-level all files", top, f"top --config {path} mid --mid {path} leaf --leaf {path}   ", 8)

# Case 2: chained group
@group(chain=True)
@option("--config", type=File("r"))
def ctop(config): pass

@ctop.command()
@option("--a", type=File("r"))
def ca(a): pass

@ctop.command()
@option("--b", type=File("r"))
def cb(b): pass

run_case("chained", ctop, f"ctop --config {path} ca --a {path} cb --b {path}   ", 7)
run_case("chained incomplete", ctop, f"ctop --config {path} ca --a {path} cb   ", 5)

# Case 3: unknown subcommand early return
@group()
def g3(): pass

@g3.command()
@option("--x", type=File("r"))
def c3(x): pass

run_case("unknown subcmd", g3, "g3 nosuchcmd   ", 2)
