import gc
import pathlib
import sys
import tempfile
import warnings

sys.path.insert(0, "/scratch/manas_ase/tmp/parbench-host-74_ep9i5/repo/src")
import click
from click.testing import CliRunner

runner = CliRunner()

def invoke_check(cli, env):
    with warnings.catch_warnings():
        warnings.simplefilter("error", ResourceWarning)
        result = runner.invoke(cli, env=env)
        gc.collect()
    assert result.exit_code == 0, (result.output, result.exception)
    assert result.exception is None, result.exception
    return result

def case1(tmp_path):
    # file value fully typed -> file opened during completion parsing
    path = tmp_path / "data.json"
    path.write_text("{}")

    @click.command()
    @click.option("--data", type=click.File("r"))
    def cli(data):
        pass

    result = invoke_check(cli, {
        "_CLI_COMPLETE": "bash_complete",
        "COMP_WORDS": f"cli --data {path} ",
        "COMP_CWORD": "3",
    })
    assert result.output == "\n", repr(result.output)
    print("case1 OK")

def case1b(tmp_path):
    # file completion visible (no value yet)
    @click.command()
    @click.option("--data", type=click.File("r"))
    def cli(data):
        pass

    result = invoke_check(cli, {
        "_CLI_COMPLETE": "bash_complete",
        "COMP_WORDS": "cli --data ",
        "COMP_CWORD": "2",
    })
    assert result.output == "file,\n", repr(result.output)
    print("case1b OK")

def case2(tmp_path):
    # group file option, complete subcommand after file value
    path = tmp_path / "data.json"
    path.write_text("{}")

    @click.group()
    @click.option("--config", type=click.File("r"))
