        "_CLI_COMPLETE": "bash_complete",
        "COMP_WORDS": f"cli --config {path} su",
        "COMP_CWORD": "3",
    })
    assert result.output == "plain,sub\n", repr(result.output)
    print("case2 OK")

def case3(tmp_path):
    # chained group with file options
    path = tmp_path / "data.json"
    path.write_text("{}")

    @click.group(chain=True)
